V=np.sum((s-s.mean())**2)
def make(fam):
    def r(x):
        g=eps**x[0]*np.exp(-x[1]*eps)/T
        if fam==0: h=T**x[2]*np.exp(x[3]/T)
        else: h=T**x[2]*np.exp(x[3]*T)
        M=np.c_[np.ones_like(T),g,h]
        co,*_=np.linalg.lstsq(M,s,rcond=None)
        return M@co-s
    return r
